return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=4; plural=((((n >= 2 && n <= 4)) && ((0 == 0))) ? 1 : ((((0 == 0)) == 0)) ? 2 : (((n == 1)) && ((0 == 0))) ? 0 : 3);','language'=>'cs_CZ','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Zálohuje vaše soubory a databázi WordPress do vašeho vlastního úložiště — Dropbox, Google Drive, Cloudflare R2, Amazon S3 nebo jakéhokoli úložiště kompatibilního s S3 —, obnovuje je jedním kliknutím a importuje zálohy vytvořené jinými pluginy pro zálohování a migraci.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Zálohy','Get Pro: schedules, several storages, encryption'=>'Získejte Pro: plány, několik úložišť, šifrování','Working…'=>'Pracuje se…','Finished'=>'Dokončeno','Failed'=>'Nezdařilo se','Cancelled'=>'Zrušeno','Cancel'=>'Zrušit','Restore'=>'Obnovit','Delete'=>'Smazat','Delete this backup from your storage? This cannot be undone.'=>'Smazat tuto zálohu z vašeho úložiště? Tuto akci nelze vrátit zpět.','No backups yet. Press “Back up now” to make the first one.'=>'Zatím žádné zálohy. Stisknutím tlačítka „Zálohovat nyní“ vytvořte první.','Reading your storage…'=>'Načítání vašeho úložiště…','a complete backup, as opposed to an incremental oneFull backup'=>'Kompletní záloha','a backup holding only what changed since an earlier oneIncremental backup'=>'Přírůstková záloha','Encrypted'=>'Zašifrováno','From another site'=>'Z jiného webu','Database'=>'Databáze','Files'=>'Soubory','Uploading %1$s: %2$s%%'=>'Nahrávání %1$s: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'V otevřeném okně se přihlaste k Dropboxu a poté vložte kód, který vám Dropbox zobrazí:','Saved.'=>'Uloženo.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Odebrat toto cílové umístění z pluginu? Zálohy v něm uložené nebudou smazány.','Reload the page to see the restored site.'=>'Obnovte stránku, abyste viděli obnovený web.','Storage'=>'Úložiště','Import & migrate'=>'Importovat a migrovat','Settings'=>'Nastavení','Sections'=>'Sekce','Google Drive is connected.'=>'Google Drive je připojen.','Google Drive could not be connected.'=>'Google Drive se nepodařilo připojit.','Details'=>'Podrobnosti','Back up now'=>'Zálohovat nyní','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Zálohy se ukládají do vašeho vlastního úložiště, nikoli na tento server. Nejprve <a href="%s">připojte své úložiště</a>.','What to back up'=>'Co zálohovat','Files and database'=>'Soubory a databáze','Database only'=>'Pouze databáze','Files only'=>'Pouze soubory','Note (optional)'=>'Poznámka (volitelné)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Každá část se nahraje do vašeho úložiště a odstraní z tohoto serveru ještě před vytvořením další části, takže záloha nikdy nezabírá místo na vašem hostingu.','Your backups'=>'Vaše zálohy','Refresh'=>'Obnovit','Restore this backup'=>'Obnovit tuto zálohu','Passphrase'=>'Přístupové heslo','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Rozumím tomu, že tímto dojde k nahrazení souborů a databáze tohoto webu zálohou. Soubory, které nejsou v záloze, zůstanou zachovány.','Recent activity'=>'Nedávná aktivita','Backup'=>'Záloha','Restore / import'=>'Obnovit / importovat','Running'=>'Spuštěno','Your storage'=>'Vaše úložiště' . "\0" . 'Vaše úložiště' . "\0" . 'Vaše úložiště' . "\0" . 'Vaše úložiště','No storage yet. Choose where your backups go below.'=>'Zatím žádné úložiště. Níže vyberte, kam se mají ukládat vaše zálohy.','Ready'=>'Připraveno','Not connected'=>'Nepřipojeno','Connect'=>'Připojit','Test'=>'Test','Edit'=>'Upravit','Remove'=>'Odstranit','Add storage'=>'Přidat úložiště','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Zálohy směřují do jednoho cílového úložiště. Chcete-li použít jiné, upravte nebo odeberte to výše.','Kind of storage'=>'Druh úložiště','Name (for you)'=>'Název (pro vás)','Provider'=>'Poskytovatel','Cloudflare account id'=>'ID účtu Cloudflare','Endpoint address'=>'Adresa koncového bodu','Region'=>'Oblast','Bucket'=>'Bucket','Access key id'=>'ID přístupového klíče','Secret access key'=>'Tajný přístupový klíč','Leave empty to keep the saved key'=>'Ponechte prázdné pro zachování uloženého klíče','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Pro Cloudflare R2: v nástěnce Cloudflare otevřete R2, vytvořte bucket, poté „Manage R2 API tokens“ → vytvořte token s oprávněním Object Read & Write pro daný bucket a zkopírujte sem access key id a secret.','Dropbox app key'=>'Klíč aplikace Dropbox','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Vytvořte aplikaci na dropbox.com/developers/apps (Scoped access, App folder) s oprávněními files.content.read, files.content.write a files.metadata.read a zkopírujte sem její App key. Uložte a poté stiskněte Connect.','OAuth client id'=>'ID klienta OAuth','OAuth client secret'=>'Tajný klíč klienta OAuth','Leave empty to keep the saved secret'=>'Ponechte prázdné pro zachování uloženého tajného klíče','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'V Google Cloud Console povolte Google Drive API a poté vytvořte klienta OAuth typu „Web application“ s touto adresou jako autorizovaným identifikátorem URI pro přesměrování:','Save, then press Connect. The plugin only sees the files it creates.'=>'Uložte a poté stiskněte Připojit. Plugin vidí pouze soubory, které sám vytvoří.','Folder inside the storage (optional)'=>'Složka v úložišti (volitelné)','Save storage'=>'Ušetřit úložiště','Import a backup from another plugin or host'=>'Importovat zálohu z jiného pluginu nebo hostingu','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Přeneste web ze zálohy vytvořené pomocí UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate nebo z libovolného archivu zip/tar webu WordPress s jeho výpisem .sql. Obsah se přesune do wp-content a databáze nahradí databázi tohoto webu; adresy se automaticky změní na adresy tohoto webu.','Upload from your computer'=>'Nahrát z počítače','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Vyberte všechny soubory zálohy najednou (UpdraftPlus jich vytváří několik). Velké soubory se odesílají po malých částech, takže se na ně nevztahuje limit pro nahrávání vašeho hostingu.','Or from links (Google Drive, Dropbox or any download address)'=>'Nebo z odkazů (Google Drive, Dropbox nebo jakákoli adresa pro stažení)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Jeden odkaz na řádek. Pro Google Drive a Dropbox nasdílejte soubor „komukoli s odkazem“ a vložte tento odkaz; poté sdílení opět vypněte.','Or a file already on this server'=>'Nebo soubor, který se již nachází na tomto serveru','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Nahrajte archivy přes FTP nebo správce souborů vašeho hostingu do %s a znovu načtěte tuto stránku.','Or a deploy code from another site'=>'Nebo kód nasazení z jiného webu','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Pokud vám jiný web poskytl kód nasazení Zinn® Backups, vložte jej sem a zkopírujte tuto zálohu na tento web bez sdílení jejích klíčů úložiště. Kód funguje několik hodin; zacházejte s ním jako s heslem.','Passphrase (only if that backup is encrypted)'=>'Heslová fráze (pouze pokud je tato záloha šifrována)','Import'=>'Importovat','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Rozumím tomu, že import nahradí obsah a databázi tohoto webu. Poté se přihlaste pomocí účtu z importovaného webu.','Moving to Zinn® hosting?'=>'Převedení hostingu k Zinn®?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® může přesunout váš web z vašeho starého hostingu za vás. Pokud vám váš starý hosting neposkytuje přístup k FTP, SSH nebo ovládacímu panelu, nainstalujte na starý web Zinn® Migrate; vytvoří jeden archiv, který můžete importovat zde nebo předat Zinn®.','What goes into a backup'=>'Co obsahuje záloha','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'Zahrnout vlastní soubory WordPress (wp-admin, wp-includes). Obvykle není potřeba: WordPress lze kdykoli přeinstalovat.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Vynechejte také tyto složky nebo soubory (jeden na řádek, relativně ke složce WordPress)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Vždy vynecháno: mezipaměti, dočasný prostor pro aktualizace a vlastní archivní složky jiných zálohovacích pluginů:','Size of each part (MB)'=>'Velikost každé části (MB)','Save settings'=>'Uložit nastavení','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Část zálohy se nepodařilo otevřít pro zápis. Zkontrolujte, zda je v adresáři wp-content volné místo.','A backup part could not be written. Check that wp-content has free space.'=>'Část zálohy se nepodařilo zapsat. Zkontrolujte, zda je ve složce wp-content volné místo.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Nejprve připojte cílové úložiště na kartě Storage: zálohy se ukládají do vašeho vlastního úložiště, nikoli na tento server.','Multisite networks are not supported yet.'=>'Sítě webů (multisite) zatím nejsou podporovány.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'PHP na tomto serveru nemá rozšíření ZipArchive. Požádejte svůj hosting o jeho povolení.','Starting'=>'Spouštění','Listing files'=>'Vypisování souborů','Backing up the database'=>'Zálohování databáze','Packing files'=>'Balení souborů','Uploading to your storage'=>'Nahrávání do vašeho úložiště','Finishing'=>'Dokončování','The backup reached an unknown stage.'=>'Záloha dosáhla neznámé fáze.','Backup %s started.'=>'Zálohování %s bylo zahájeno.','Found %1$s files (%2$s).'=>'Nalezeno %1$s souborů (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Databáze: %1$d tabulek, %2$s řádků, %3$s komprimováno.','Backup complete: %1$s stored in %2$d destination.'=>'Záloha dokončena: %1$s uloženo v %2$d cíli.' . "\0" . 'Zálohování dokončeno: %1$s uloženo v %2$d umístěních.' . "\0" . 'Zálohování dokončeno: %1$s uloženo v %2$d umístěních.' . "\0" . 'Zálohování dokončeno: %1$s uloženo v %2$d umístěních.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Některé již nahrané součásti se nepodařilo z vašeho úložiště odstranit; nacházejí se ve složce neúplné zálohy a nikdy nebudou nabídnuty k obnovení.','A storage destination was removed while the backup was running.'=>'Cílové úložiště bylo odebráno v průběhu zálohování.','That is not a backup folder.'=>'Toto není složka se zálohou.','That storage destination is no longer saved on this site.'=>'Toto úložiště již není na tomto webu uloženo.','Later incremental backups are built on this one. Delete those first.'=>'Pozdější přírůstkové zálohy jsou postaveny na této. Nejprve odstraňte je.','This file is not an encrypted Zinn® Backups file.'=>'Tento soubor není šifrovaný soubor Zinn® Backups.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'Zálohu se nepodařilo dešifrovat: heslo je nesprávné nebo je soubor poškozen.','The encrypted backup file is incomplete.'=>'Zašifrovaný soubor zálohy je neúplný.','The database file could not be written. Check that wp-content has free space.'=>'Soubor databáze se nepodařilo zapsat. Zkontrolujte, zda má složka wp-content volné místo.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'Toto není kód pro nasazení. Kód pro nasazení začíná na zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'Tento kód pro nasazení je poškozený. Zkopírujte jej znovu z druhého webu.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Platnost nasazovacího kódu vypršela nebo byla smazána jeho záloha. Vytvořte nový kód na druhém webu.','That deploy code does not point at a Zinn® Backups backup.'=>'Tento kód nasazení neodkazuje na zálohu Zinn® Backups.','The deploy code has expired. Make a new code on the other site.'=>'Platnost kódu pro nasazení vypršela. Vytvořte nový kód na druhém webu.','The server stopped honouring partial downloads. Start the import again.'=>'Server přestal podporovat částečné stahování. Spusťte import znovu.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Odkaz otevřel webovou stránku místo souboru. V případě Google Drive a Dropboxu sdílejte soubor s volbou „kdokoli s odkazem“ a vložte tento odkaz.','The link answered with HTTP %d.'=>'Odkaz odpověděl s HTTP %d.','The file list could not be written.'=>'Seznam souborů se nepodařilo zapsat.','The storage service could not be reached: %s'=>'Ke službě úložiště se nelze připojit: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s odpověděl s HTTP %2$d: %3$s','no details given'=>'Nebyly uvedeny žádné podrobnosti','You are not allowed to manage backups.'=>'Nemáte oprávnění ke správě záloh.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Zaškrtnutím políčka potvrďte, že obnovení nahradí soubory a databázi tohoto webu.','Save the destination first.'=>'Nejprve uložte cíl.','Connected: a test file was written and removed.'=>'Připojeno: testovací soubor byl zapsán a odstraněn.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Nejprve zadejte klíč své aplikace Dropbox (viz kroky vedle formuláře).','This kind of storage does not sign in.'=>'Tento typ úložiště se nepřihlašuje.','The sign-in expired. Press Connect again.'=>'Platnost přihlášení vypršela. Stiskněte znovu Připojit.','Dropbox is connected.'=>'Dropbox je připojen.','Settings saved.'=>'Nastavení uloženo.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Právě probíhá jiná záloha, obnovení nebo import. Počkejte na dokončení, nebo operaci zrušte.','The upload was not started properly. Start again.'=>'Nahrávání nebylo správně spuštěno. Začněte znovu.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Část nedorazila. Váš server může omezovat velikost nahrávaných souborů; zkuste to znovu.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Zaškrtnutím políčka potvrďte, že import nahradí obsah a databázi tohoto webu.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Vyberte archiv k importu: nahrajte jej, vložte odkaz nebo vyberte soubor ze složky pro import.','Hosting customer? Get %1$d%% off %2$s'=>'Zákazník hostingu? Získejte slevu %1$d %% na %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Jako zákazník hostingu Zinn Digital® získáte osobní kód na slevu %d%% z vaší první platby. Obnovení jsou za běžnou cenu.','Get my %d%% code and go to checkout'=>'Získejte můj %d%% kód a přejděte k pokladně','Sorry, you are not allowed to do that.'=>'Omlouváme se, ale k této akci nemáte oprávnění.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Tato sleva je určena pro zákazníky s aktivním a řádně hrazeným hostingovým tarifem. Bezplatné zkušební verze nemají nárok.','You have already used your hosting-customer discount for this plugin.'=>'Svou slevu pro zákazníky hostingu pro tento plugin jste již využili.','We could not get your code just now. Please try again in a few minutes.'=>'Váš kód se nám právě nepodařilo získat. Zkuste to prosím znovu za několik minut.','Reading the backup'=>'Načítání zálohy','Downloading the archive'=>'Stahování archivu','Recognising the archive'=>'Rozpoznávání archivu','Restoring files'=>'Obnovování souborů','Downloading the database'=>'Stahování databáze','Restoring the database'=>'Obnovování databáze','Updating the site address'=>'Aktualizace adresy webu','Switching to the restored database'=>'Přepínání na obnovenou databázi','The restore reached an unknown stage.'=>'Obnovení dosáhlo neznámé fáze.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Tato složka neobsahuje žádnou úplnou zálohu Zinn® Backups (chybí manifest).','This backup is encrypted. Enter its passphrase to restore it.'=>'Tato záloha je zašifrována. Pro její obnovení zadejte přístupovou frázi.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Tato přírůstková záloha vyžaduje zálohu %s, která se již v úložišti nenachází.','Restoring the backup of %1$s (%2$d file parts).'=>'Obnovuje se záloha %1$s (%2$d částí souboru).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'Soubor %1$s nelze přepsat, protože tento web nemá oprávnění jej měnit, a byl ponechán ve stávajícím stavu: %2$s' . "\0" . 'Soubory (%1$s) nebylo možné přepsat, protože tento web nemá oprávnění je měnit, a byly ponechány beze změny: %2$s' . "\0" . 'Soubory (%1$s) nebylo možné přepsat, protože tento web nemá oprávnění je měnit, a byly ponechány beze změny: %2$s' . "\0" . 'Soubory (%1$s) nebylo možné přepsat, protože tento web nemá oprávnění je měnit, a byly ponechány beze změny: %2$s','Restored %s files.'=>'Bylo obnoveno %s souborů.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'Soubor %s se po stažení neshodoval se svým kontrolním součtem. Kopie v úložišti může být poškozena.','%s did not arrive. Upload it again.'=>'Položka %s nedorazila. Nahrajte ji prosím znovu.','Recognised: %s.'=>'Rozpoznáno: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'Do wp-content bylo importováno %1$s souborů (%2$s vynecháno: mezipaměti, drop-iny a složky ostatních zálohovacích pluginů).','The archive has no database dump, so only files were imported.'=>'Archiv neobsahuje žádný výpis databáze, proto byly importovány pouze soubory.','Database restored into %d temporary tables.'=>'Databáze byla obnovena do %d dočasných tabulek.','%s has no WordPress tables in it and was skipped.'=>'%s neobsahuje žádné tabulky WordPress a byl přeskočen.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'Databáze zálohy neobsahuje žádné tabulky WordPress, takže nebylo nic nahrazeno.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Tato záloha pochází ze sítě webů (multisite). Obnovení sítě na samostatný web není podporováno.','Moving the content from %1$s to %2$s.'=>'Přesouvání obsahu z %1$s do %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Obnovení bylo dokončeno. Pokud jste byli odhlášeni, přihlaste se pomocí účtu z obnoveného webu.','Restore complete.'=>'Obnovení dokončeno.','%1$s — trying again in %2$d seconds.'=>'%1$s — opakovaný pokus za %2$d sekund.','Cancelled.'=>'Zrušeno.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Zálohy směřují do jednoho cílového úložiště. Chcete-li použít jiné, upravte nebo odstraňte to stávající.','The database file could not be opened.'=>'Soubor databáze se nepodařilo otevřít.','The database refused a statement from the backup: %1$s (%2$s…)'=>'Databáze odmítla příkaz ze zálohy: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Obnovené tabulky se nepodařilo nahradit: %s. Váš web zůstal beze změny.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Neexistuje žádná zapisovatelná složka pro dočasné záložní soubory. Nastavte pro wp-content oprávnění k zápisu a zkuste to znovu.','Could not create a folder for this job.'=>'Pro tuto úlohu se nepodařilo vytvořit složku.','%s — guides and services'=>'%s — návody a služby','User guides'=>'Uživatelské příručky','Read the %s user guide'=>'Přečtěte si uživatelskou příručku %s','Hide this'=>'Skrýt toto','Zinn® hosting for WordPress'=>'Zinn® hosting pro WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, denní zálohy, bezplatná migrace a ovládací panel vytvořený pro lidi, kteří spravují více než jeden web.','The Zinn® marketplace'=>'Tržiště Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte a prodávejte zavedené weby, domény a umístění odkazů s penězi bezpečně uschovanými, dokud nebudou obě strany spokojené.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — najměte si lidi, kteří se tím živí','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globální tržiště na volné noze: procházejte více než 10 000 hotových služeb od autorů, designérů, vývojářů a SEO specialistů, nebo zadejte projekt a nechte je podávat nabídky.','See the Zinn Digital® release notes.'=>'Zobrazit poznámky k vydání Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Aktualizační služba Zinn® nevydala odkaz ke stažení této aktualizace. Zkontrolujte, zda se tento web může připojit k platformě Zinn®, a zkuste to znovu.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Aktualizaci se nepodařilo stáhnout ze služby aktualizací Zinn® (%s). Zkuste to znovu za několik minut.','The downloaded update failed its integrity check and was not installed.'=>'Stažená aktualizace neprošla kontrolou integrity a nebyla nainstalována.','The zip archive could not be opened. It may be damaged or incomplete.'=>'Archiv zip se nepodařilo otevřít. Může být poškozený nebo neúplný.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Tento soubor .wpress používá formát, který neumíme přečíst (může být komprimován nebo šifrován doplňkem All-in-One WP Migration). Exportujte jej prosím znovu bez šifrování.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Toto je soubor Duplicator „DupArchive“ (.daf). V doplňku Duplicator vytvořte balíček znovu s formátem archivu nastaveným na ZIP a poté jej importujte.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Tato záloha databáze UpdraftPlus je zašifrována. Dešifrujte ji v UpdraftPlus (nebo vypněte šifrování databáze a zálohujte znovu) a poté ji importujte.','Database dump'=>'Výpis databáze','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s není archiv zálohy, který dokážeme přečíst (zip, tar, tar.gz, .wpress, .sql nebo .sql.gz).','Website archive'=>'Archiv webu','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s neobsahuje žádný obsah WordPress (žádnou složku wp-content ani export databáze).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Tento soubor .wpress je zašifrován nebo komprimován pomocí All-in-One WP Migration. Exportujte jej prosím znovu s vypnutým šifrováním a kompresí a poté jej importujte.','Other S3-compatible storage'=>'Jiné úložiště kompatibilní s S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 nebo kompatibilní s S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Klíče úložiště se na tomto webu nepodařilo přečíst. Zadejte tajný klíč znovu na kartě Úložiště.','This kind of storage is not known.'=>'Tento typ úložiště není znám.','Choose a kind of storage.'=>'Vyberte typ úložiště.','Enter the bucket name and the access key.'=>'Zadejte název bucketu a přístupový klíč.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Zadejte ID svého účtu Cloudflare (nebo úplný koncový bod R2).','Enter the endpoint address of your storage.'=>'Zadejte adresu koncového bodu vašeho úložiště.','Enter the OAuth client id from your Google Cloud project.'=>'Zadejte OAuth client id ze svého projektu Google Cloud.','Dropbox did not return a refresh token. Start the connection again.'=>'Služba Dropbox nevrátila obnovovací token. Zahajte připojení znovu.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox není připojen. Připojte jej znovu na kartě Úložiště.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google nevrátil obnovovací token. Odeberte tento web z přístupu třetích stran ve svém účtu Google a znovu se připojte.','That file is not in Google Drive any more.'=>'Tento soubor již není na Google Drive.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive není připojen. Připojte jej znovu na kartě Úložiště.','The storage service did not start the upload.'=>'Úložiště nespustilo nahrávání.','The storage service sent a reply that could not be read.'=>'Úložiště odeslalo odpověď, kterou nelze přečíst.','A temporary backup file could not be read.'=>'Dočasný záložní soubor se nepodařilo přečíst.','A deploy link is read-only.'=>'Odkaz pro nasazení je pouze pro čtení.','The deploy code has no link for a file this backup needs.'=>'Kód nasazení neobsahuje odkaz na soubor, který tato záloha potřebuje.','The deploy link'=>'Odkaz na nasazení']];